<?php require 'includes/auth.php';require 'config/database.php';require 'includes/csrf.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();$pdo->prepare('INSERT INTO cells(block_name,cell_number,capacity,status) VALUES(?,?,?,?)')->execute([trim($_POST['block_name']),trim($_POST['cell_number']),$_POST['capacity'],trim($_POST['status'])]);header('Location: cells.php');exit;}$rows=$pdo->query('SELECT * FROM cells ORDER BY id DESC')->fetchAll();$title='Cells';require 'includes/header.php';?><div class="row g-4"><div class="col-lg-4"><div class="box"><h4>Add Cells</h4><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label class="form-label mt-2">Block</label><input class="form-control" type="text" name="block_name" required><label class="form-label mt-2">Cell Number</label><input class="form-control" type="text" name="cell_number" required><label class="form-label mt-2">Capacity</label><input class="form-control" type="number" name="capacity" required><label class="form-label mt-2">Status</label><input class="form-control" type="text" name="status" required><button class="btn btn-primary mt-3">Save</button></form></div></div><div class="col-lg-8"><div class="box"><h2>Cells</h2><div class="table-responsive"><table class="table"><tr><th>Block</th><th>Cell Number</th><th>Capacity</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['block_name'])?></td><td><?=htmlspecialchars($r['cell_number'])?></td><td><?=htmlspecialchars($r['capacity'])?></td><td><?=htmlspecialchars($r['status'])?></td></tr><?php endforeach;?></table></div></div></div></div><?php require 'includes/footer.php';?>